dataModel.addDataPropertyChangeListener(function (e) {

    const chanProperties = ['a:chan1', 'a:chan2', 'a:chan3'];
    if (chanProperties.includes(e.property)) {
    const tips = e.newValue;
    console.log(`📥 收到 chan系列数据 ${e.property}：`, tips);

    const chanSeriesMap = {
        'a:chan1': 0,
        'a:chan2': 1,
        'a:chan3': 2
    };
    const targetIndex = chanSeriesMap[e.property];

    // 提取y轴数据（Wt值，按需格式化）
    const yData = tips.map(item => Number(item.Wt)); // 保留2位小数

    // 获取chan系列对应的图表（假设tag为"chanChart"，与x系列图表分开）
    const chanChartData = graphView.dm().getDataByTag('chartUseBinding'); // 独立图表tag
    let chanSeries = chanChartData.a('ht.series');
    // 更新对应系列的y数据
    chanSeries[targetIndex].data = yData;
    chanChartData.a('ht.series', chanSeries);

    // 处理x轴（仅首次更新，因chan1-3的x轴一致）
    const xAxis = chanChartData.a('ht.xAxis');
        // 从当前chan数据中提取x轴（Time格式化为"月-日"）
        const xData = tips.map(item => item.Time.slice(5, 10)); // 如"10-27"
        xAxis[0].data = xData;
        console.log(xData)
        chanChartData.a('xAxis', xAxis);
    }

    if (['a:ge1', 'a:ge2', 'a:ge3', 'a:ge4', 'a:ge5'].includes(e.property)) {
    // 1. 获取原始数值数组（e.newValue 直接是 [10,20,30,40]）
    const rawValueArray = e.newValue;
    const processedArray = rawValueArray.map(item => {
        const num = Number(item);
        return num; 
    });

    // 3. 映射目标系列索引（x1→0，x2→1...）
    const seriesMap = { 'a:ge1':0, 'a:ge2':1, 'a:ge3':2, 'a:ge4':3, 'a:ge5':4 };
    const targetSeriesIndex = seriesMap[e.property];

    // 4. 获取图表系列数据
    const chartData = graphView.dm().getDataByTag('Mid_2_1');
    console.log('获取到的chartData：', chartData); 
    const series = chartData.a('ht.series'); 
    series[targetSeriesIndex].data.value = processedArray;

    // 5. 刷新图表
    chartData.a('ht.series', series);
    console.log(`✅ ${e.property} 已更新，数据：`, processedArray);
    }

    if (e.property === 'a:isWar') {
        const group = e.newValue;
        const groupMap = {
        'A': '甲班',
        'B': '乙班',
        'C': '丙班',
        'D': '丁班'
        };

        const className = groupMap[group] || '未知班级';
        let groupNode = graphView.dm().getDataByTag('班组');
        console.log(groupNode)
        groupNode.s('text', className);
        console.log('📥 收到 group 数据：', e.newValue);
    }

    if (e.property === 'a:rolltable') {
        let tips = e.newValue;
        console.log('📥 收到 rolltable 数据：', tips);
        const timeArray = []; 
        const rollDurArray = [];

        tips.forEach(item => {
            if (item.hasOwnProperty('Time')) {
                const monthDay = item.Time.slice(5, 10);
                timeArray.push(monthDay);
            }
            if (item.hasOwnProperty('RollDur')) {
                // 转为数值并保留一位小数
                const energy = Number(parseFloat(item.RollDur*100).toFixed(1));
                rollDurArray.push(energy);
            }
        });

    // 获取图表数据模型
        let tableData = graphView.dm().getDataByTag('lefttable1');
        let xAxis = tableData.a('xAxis');
        let yAxis = tableData.a('yAxis');
        console.log(yAxis)
        let series = tableData.a('series');
        xAxis[0].data = timeArray;
        series[0].data = rollDurArray; 
        tableData.a('xAxis', xAxis);
        tableData.a('series', series);
    };

    if (e.property === 'a:rolltable1') {
        let tips = e.newValue;
        console.log('📥 收到 rolltable 数据：', tips);
        const timeArray = []; 
        const rollDurArray = [];

        tips.forEach(item => {
            if (item.hasOwnProperty('Date')) {
                const monthDay = item.Date.slice(5, 10);
                timeArray.push(monthDay);
            }
            if (item.hasOwnProperty('EnergyConsum')) {
                // 转为数值并保留一位小数
                const energy = Number(parseFloat(item.EnergyConsum).toFixed(1));
                rollDurArray.push(energy);
            }
        });

        // 获取图表数据模型
        let tableData = graphView.dm().getDataByTag('lefttable2');
        let xAxis = tableData.a('xAxis');
        let yAxis = tableData.a('yAxis');
        let series = tableData.a('series');
        xAxis[0].data = timeArray;
        series[0].data = rollDurArray; 
        tableData.a('xAxis', xAxis);
        tableData.a('series', series);
        console.log(xAxis,yAxis)
    };
    
    if (e.property === 'a:chanliang') {
        let tips = e.newValue;
        console.log(tips)
        let proWtRate = graphView.dm().getDataByTag('proWtRate');
        let scrapWtRate = graphView.dm().getDataByTag('scrapWtRate');
        let rejectWtRate = graphView.dm().getDataByTag('rejectWtRate');
        proWtRate.a('value',parseFloat(tips.proWtRate).toFixed(2));
        scrapWtRate.a('value',tips.scrapWtRate);
        rejectWtRate.a('value',tips.rejectWtRate);
        // 转换逻辑：遍历对象的键，生成包含 name 和 value 的数组
        const result = Object.keys(tips).map(key => ({
              name: key,          // 键名作为 name（如 "proWtRate"）
              value: tips[key]  // 键值乘以 100（原 1 对应 100，符合示例）
        }));
        let pie2 = graphView.dm().getDataByTag('pie2');
        pie2.a('dataSource',result)
    };

    if (e.property === 'a:tingji') {
        let tips = e.newValue;
        console.log(tips)
        let mouth1 = graphView.dm().getDataByTag('RollDurRate_Month');
        let mouth2 = graphView.dm().getDataByTag('ProFaultTimeRate_Month');
        let mouth3 = graphView.dm().getDataByTag('STOP_TIMERate_Month');
        let mouth4 = graphView.dm().getDataByTag('RollDurRate_PerMonth');
        let mouth5 = graphView.dm().getDataByTag('ProFaultTimeRate_PerMonth');
        let mouth6 = graphView.dm().getDataByTag('STOP_TIMERate_PerMonth');
        mouth1.a('value',tips.RollDurRate_Month);
        mouth2.a('value',tips.ProFaultTimeRate_Month);
        mouth3.a('value',tips.STOP_TIMERate_Month);
        mouth4.a('value',tips.RollDurRate_PerMonth);
        mouth5.a('value',tips.ProFaultTimeRate_PerMonth);
        mouth6.a('value',tips.STOP_TIMERate_PerMonth);
        // 定义需要排除的键（不显示在饼图中的字段）
        const excludeKeys = [
        'RollDurRate_PerMonth',
        'ProFaultTimeRate_PerMonth',
        'STOP_TIMERate_PerMonth'
        ];

        // 转换逻辑：先过滤排除不需要的键，再生成饼图数据
        const result = Object.keys(tips)
        .filter(key => !excludeKeys.includes(key)) // 只保留不在排除列表中的键
        .map(key => ({
            name: key,
            value: tips[key] // 根据需要调整value计算方式
        }));
        let pie1 = graphView.dm().getDataByTag('pie1');
        pie1.a('dataSource',result)
    };


});
